(199106), (65768), (74706), (1120), (72506), (74709), (86958), (210), (197221), (66155), (220192), (187), (1021), (71958), (1514), (791), (1171), (734), (298546), (88286), (606), (558), (68738), (197688), (77726), (1603), (90895), (79819), (227), (212), (197681), (756), (95184), (722), (74132), (1244), (445), (1049), (757), (82467), (1422), (206), (65769), (304429), (983), (286), (773), (771), (254), (216190), (1013), (82554), (260317), (446), (205), (81930), (215221), (750), (204216), (201003), (65954), (93115), (92578), (1285), (74694), (204429), (84913), (204362), (198236), (202764), (1045), (289877), (76140), (86882), (71261), (166)) AS t(id) ) , route_category AS ( SELECT DISTINCT src_id, dest_id, traffic, CASE WHEN s_cat = 'Leisure' OR d_cat = 'Leisure' THEN 'Leisure' WHEN s_cat = 'Pilgrim' OR d_cat = 'Pilgrim' THEN 'Pilgrim' ELSE COALESCE(s_cat, 'Tier 3') || ' - ' || COALESCE(d_cat, 'Tier 3') END AS route_category FROM ( SELECT src_id, dest_id, s.cat as s_cat, d.cat as d_cat, COUNT(DISTINCT mri_session_id) traffic FROM "user_interaction"."search_route_details" base LEFT JOIN all_ids s ON base.src_id = s.id LEFT JOIN all_ids d ON base.dest_id = d.id WHERE 1=1 AND __time >= TIMESTAMP '2025-10-01 00:00:00' AND __time < TIMESTAMP '2026-01-01 00:00:00' AND country = 'IND' AND status = 200 AND tp_channel = 'INVALID' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND (akamai_bot IS NULL OR akamai_bot = '') GROUP BY 1,2,3,4 ) ) , relevant_routes AS ( SELECT src_id, dest_id, route_category, traffic FROM route_category WHERE route_category LIKE '%Tier 3%' ) , Inv AS ( SELECT source_id, destination_id, doj, COUNT(DISTINCT route_id) service_count FROM "inventory"."inventory" WHERE doj > DATE '2025-10-01' AND doj < DATE '2026-01-01' AND (source_id, destination_id) IN (SELECT DISTINCT src_id, dest_id FROM relevant_routes) GROUP BY 1,2,3 -- LIMIT 100 ), Txn AS ( SELECT source_location_id, destination_location_id, COUNT(DISTINCT tin) txn_count FROM "transaction"."bus_ticket_events" WHERE 1 = 1 AND date_of_issue >= TIMESTAMP '2025-10-01 00:00:00' AND date_of_issue < TIMESTAMP '2026-01-01 00:00:00' AND event_type = 101 AND event_class = 2 AND country_code = 'IND' AND (source_location_id, destination_location_id) IN (SELECT DISTINCT src_id, dest_id FROM relevant_routes) GROUP BY 1,2 ) SELECT CAST(r.src_id AS VARCHAR) ||'-'|| CAST(r.dest_id AS VARCHAR) AS SD_ID, (src.location_name ||'-'|| dest.location_name) AS route, r.route_category route_tier, CASE WHEN (r.src_id, r.dest_id) IN (SELECT DISTINCT src_id, dest_id FROM short_routes) THEN 'Short Routes' ELSE 'Long Routes' END AS route_cohort, approx_percentile(service_count,0.5) median_tuples_count, MAX(r.traffic) traffic, MAX(txn_count) txn_count FROM relevant_routes r LEFT JOIN Inv i ON i.source_id = r.src_id AND i.destination_id = r.dest_id LEFT JOIN Txn t ON i.source_id = t.source_location_id AND i.destination_id =t.destination_location_id LEFT JOIN "lis"."config_locations" src ON src.id = i.source_id LEFT JOIN "lis"."config_locations" dest ON dest.id = i.destination_id GROUP BY 1,2,3,4
